import pytest
import json
from pathlib import Path

# Constants
UPLOAD_IMAGE_ENDPOINT = "/pet/{}/uploadImage"

@pytest.mark.parametrize("pet_id, metadata, file_data, expected_status, scenario_description", [
    (12345, "sample metadata", b"sample image data", 200, "Valid pet ID, valid metadata, and valid file data"),
    (12345, None, None, 400, "Valid pet ID but no file uploaded"),
    (99999, None, b"sample image data", 404, "Non-existent pet ID"),
    (12345, "sample metadata", None, 400, "Valid pet ID and metadata but no file uploaded"),
])
def test_upload_image(
    pet_id,
    metadata,
    file_data,
    expected_status,
    scenario_description,
    api_client,
    valid_api_key
):
    """
    Test /pet/{petId}/uploadImage endpoint for different scenarios.
    This function verifies success, error codes, and edge cases.
    """
    # Construct endpoint with the petId in the URL
    endpoint = UPLOAD_IMAGE_ENDPOINT.format(pet_id)

    # Build headers
    headers = {"Authorization": f"Bearer {valid_api_key}"}

    # Build query parameters
    params = {"additionalMetadata": metadata} if metadata else {}

    # Make the request
    if file_data:
        response = api_client.post(
            endpoint=endpoint, headers=headers, params=params, data=file_data
        )
    else:
        response = api_client.post(endpoint=endpoint, headers=headers, params=params)

    # Assertions
    assert response.status_code == expected_status, f"Failed: {scenario_description}"

    if expected_status == 200:
        response_data = response.json()
        assert "code" in response_data, "Missing 'code' in response JSON"
        assert "type" in response_data, "Missing 'type' in response JSON"
        assert "message" in response_data, "Missing 'message' in response JSON"
        # Additional schema validation, if required

    elif expected_status == 400:
        assert "No file uploaded" in response.text, "Error message mismatch for 400"

    elif expected_status == 404:
        assert "Pet not found" in response.text, "Error message mismatch for 404"


